svg.script:
(function() {
  const BB = { x: 475, y: 420 };
  const CRANK_R = 38;
  const HIP_NEAR = { x: 390, y: 285 };
  const HIP_FAR  = { x: 405,  y: 280 };
  const THIGH_LEN = 110;
  const SHIN_LEN  = 105;

  const nearCrankArm = document.getElementById('nearCrankArm');
  const nearCrankPin = document.getElementById('nearCrankPin');
  const nearPedalGroup = document.getElementById('nearPedalGroup');
  const nearThigh = document.getElementById('nearThigh');
  const nearShin = document.getElementById('nearShin');
  const nearKneeCap = document.getElementById('nearKneeCap');
  const nearFootGroup = document.getElementById('nearFootGroup');

  const farCrankArm = document.getElementById('farCrankArm');
  const farCrankPin = document.getElementById('farCrankPin');
  const farPedalGroup = document.getElementById('farPedalGroup');
  const farThigh = document.getElementById('farThigh');
  const farShin = document.getElementById('farShin');
  const farFootGroup = document.getElementById('farFootGroup');

  const pelicanRiderGroup = document.getElementById('pelicanRiderGroup');
  const throatPouchPath = document.getElementById('throatPouchPath');
  const pedalShadowNear = document.getElementById('pedalShadowNear');

  function solve2LinkIK(hipX, hipY, pedalX, pedalY, l1, l2) {
    const dx = pedalX - hipX;
    const dy = pedalY - hipY;
    const dist = Math.hypot(dx, dy);
    const phi = Math.atan2(dy, dx);

    const cosAlpha = (l1 * l1 + dist * dist - l2 * l2) / (2 * l1 * dist);
    const clampedCos = Math.max(-1.0, Math.min(1.0, cosAlpha));
    const alpha = Math.acos(clampedCos);

    const thighAngle = phi - alpha;
    const kneeX = hipX + l1 * Math.cos(thighAngle);
    const kneeY = hipY + l1 * Math.sin(thighAngle);

    const shinAngle = Math.atan2(pedalY - kneeY, pedalX - kneeX);
    return { kneeX, kneeY, thighAngle, shinAngle };
  }

  let startTime = performance.now();
  let speed = 1.0;

  function animate(time) {
    const elapsed = (time - startTime) / 1000;
    const crankAngle = (elapsed * speed * 2 * Math.PI) % (2 * Math.PI);

    // Body Dynamics
    const bobY = Math.sin(crankAngle * 2) * 3.8;
    const rockAngle = Math.sin(crankAngle) * 1.5;
    if (pelicanRiderGroup) {
      pelicanRiderGroup.setAttribute('transform', `translate(0, ${bobY}) rotate(${rockAngle}, 390, 285)`);
    }

    // Throat Pouch Elastic Jiggle
    if (throatPouchPath) {
      const pouchJiggle = Math.sin(crankAngle * 2 - 0.5) * 4;
      throatPouchPath.setAttribute('d', 
        `M 525 140 C 560 150 630 165 655 170 C 625 ${215 + pouchJiggle} 565 ${245 + pouchJiggle * 1.4} 505 200 C 495 170 515 145 525 140 Z`
      );
    }

    const curNearHip = { x: HIP_NEAR.x, y: HIP_NEAR.y + bobY };
    const curFarHip  = { x: HIP_FAR.x,  y: HIP_FAR.y  + bobY };

    // Near Side Pedal & Leg (Foreground)
    const nearPedalX = BB.x + CRANK_R * Math.cos(crankAngle);
    const nearPedalY = BB.y + CRANK_R * Math.sin(crankAngle);

    if (nearCrankArm) {
      nearCrankArm.setAttribute('x1', BB.x);
      nearCrankArm.setAttribute('y1', BB.y);
      nearCrankArm.setAttribute('x2', nearPedalX);
      nearCrankArm.setAttribute('y2', nearPedalY);
    }
    if (nearCrankPin) {
      nearCrankPin.setAttribute('cx', nearPedalX);
      nearCrankPin.setAttribute('cy', nearPedalY);
    }

    const nearFootTilt = Math.sin(crankAngle) * 8;
    if (nearPedalGroup) {
      nearPedalGroup.setAttribute('transform', `translate(${nearPedalX}, ${nearPedalY}) rotate(${nearFootTilt * 0.4})`);
    }

    const nearIK = solve2LinkIK(curNearHip.x, curNearHip.y, nearPedalX, nearPedalY, THIGH_LEN, SHIN_LEN);

    if (nearThigh) {
      const midThighX = (curNearHip.x + nearIK.kneeX) / 2 - 8;
      const midThighY = (curNearHip.y + nearIK.kneeY) / 2 + 5;
      nearThigh.setAttribute('d', `M ${curNearHip.x} ${curNearHip.y} Q ${midThighX} ${midThighY} ${nearIK.kneeX} ${nearIK.kneeY}`);
    }
    if (nearShin) {
      nearShin.setAttribute('d', `M ${nearIK.kneeX} ${nearIK.kneeY} L ${nearPedalX} ${nearPedalY}`);
    }
    if (nearKneeCap) {
      nearKneeCap.setAttribute('cx', nearIK.kneeX);
      nearKneeCap.setAttribute('cy', nearIK.kneeY);
    }
    if (nearFootGroup) {
      nearFootGroup.setAttribute('transform', `translate(${nearPedalX}, ${nearPedalY}) rotate(${nearFootTilt})`);
    }
    if (pedalShadowNear) {
      pedalShadowNear.setAttribute('cx', nearPedalX);
    }

    // Far Side Pedal & Leg (Background, 180° Phase Offset)
    const farAngle = crankAngle + Math.PI;
    const farPedalX = BB.x + CRANK_R * Math.cos(farAngle);
    const farPedalY = BB.y + CRANK_R * Math.sin(farAngle);

    if (farCrankArm) {
      farCrankArm.setAttribute('x1', BB.x);
      farCrankArm.setAttribute('y1', BB.y);
      farCrankArm.setAttribute('x2', farPedalX);
      farCrankArm.setAttribute('y2', farPedalY);
    }
    if (farCrankPin) {
      farCrankPin.setAttribute('cx', farPedalX);
      farCrankPin.setAttribute('cy', farPedalY);
    }

    const farFootTilt = Math.sin(farAngle) * 8;
    if (farPedalGroup) {
      farPedalGroup.setAttribute('transform', `translate(${farPedalX}, ${farPedalY}) rotate(${farFootTilt * 0.4})`);
    }

    const farIK = solve2LinkIK(curFarHip.x, curFarHip.y, farPedalX, farPedalY, THIGH_LEN, SHIN_LEN);

    if (farThigh) {
      const midFarThighX = (curFarHip.x + farIK.kneeX) / 2 - 6;
      const midFarThighY = (curFarHip.y + farIK.kneeY) / 2 + 4;
      farThigh.setAttribute('d', `M ${curFarHip.x} ${curFarHip.y} Q ${midFarThighX} ${midFarThighY} ${farIK.kneeX} ${farIK.kneeY}`);
    }
    if (farShin) {
      farShin.setAttribute('d', `M ${farIK.kneeX} ${farIK.kneeY} L ${farPedalX} ${farPedalY}`);
    }
    if (farFootGroup) {
      farFootGroup.setAttribute('transform', `translate(${farPedalX}, ${farPedalY}) rotate(${farFootTilt})`);
    }

    requestAnimationFrame(animate);
  }

  requestAnimationFrame(animate);
})();
